<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount } from 'vue';
import { ArrowUpRight, ArrowRight, Asterisk, GitBranch, Github, Layers, Link2, CircleAlert, Box, Search, ChevronRight, Check, X, ExternalLink, LoaderCircle, Activity, Fingerprint, Copy } from 'lucide-vue-next';
import DependencyGraph from './components/DependencyGraph.vue';
import { demo, githubUrl, connections } from './model';
import type { Analysis } from './model';
const searchInput=ref<HTMLInputElement>();
function shortcut(event:KeyboardEvent){if(event.key==='/'&&!(event.target instanceof HTMLInputElement)&&!(event.target instanceof HTMLTextAreaElement)){event.preventDefault();tab.value='modules';setTimeout(()=>searchInput.value?.focus(),0)}}
const url=ref(''), branch=ref(''), data=ref<Analysis>(demo), isDemo=ref(true), loading=ref(false), error=ref(''), selected=ref<string|null>('shared-kernel'), query=ref(''), cyclesOnly=ref(false), copied=ref(false), tab=ref<'modules'|'insights'>('modules');
let controller:AbortController|undefined;
const current=computed(()=>data.value.nodes.find(n=>n.id===selected.value));
const filtered=computed(()=>data.value.nodes.filter(n=>`${n.label} ${n.path}`.toLowerCase().includes(query.value.toLowerCase())));
const ranked=computed(()=>[...data.value.nodes].sort((a,b)=>connections(data.value,b.id)-connections(data.value,a.id)).slice(0,5));
const incoming=computed(()=>data.value.edges.filter(e=>e.target===selected.value));
const outgoing=computed(()=>data.value.edges.filter(e=>e.source===selected.value));
const name=(id:string)=>data.value.nodes.find(n=>n.id===id)?.label??id;
async function analyze(){error.value='';if(!githubUrl(url.value.trim())){error.value='Enter a full public repository URL, like https://github.com/apache/maven.';return}loading.value=true;controller?.abort();controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),180000);try{const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:url.value.trim(),...(branch.value.trim()?{ref:branch.value.trim()}:{})}),signal:controller.signal});const body=await response.json().catch(()=>null);if(!response.ok)throw new Error(body?.message||`Analysis failed (${response.status}). Please try again.`);if(!body?.repository||!Array.isArray(body.nodes)||!Array.isArray(body.edges)||!body.stats)throw new Error('The server returned an unexpected report. Please try again.');data.value={...body,cycles:body.cycles??[],warnings:body.warnings??[]};isDemo.value=false;selected.value=body.nodes[0]?.id??null;cyclesOnly.value=false;const share=new URL(window.location.href);share.search='';share.searchParams.set('repo',url.value.trim());if(body.repository.ref)share.searchParams.set('ref',body.repository.ref);window.history.replaceState({},'',share);}catch(e){error.value=e instanceof Error?(e.name==='AbortError'?'Analysis timed out or was canceled. Try a smaller repository or try again.':e.message):'Could not connect to the analyzer. Please try again.'}finally{clearTimeout(timeout);loading.value=false}}
async function share(){try{await navigator.clipboard.writeText(window.location.href);copied.value=true;setTimeout(()=>copied.value=false,2200)}catch{error.value='Clipboard unavailable. Copy the URL from your browser address bar to share this analysis.'}}
function loadDemo(){controller?.abort();data.value=demo;isDemo.value=true;selected.value='shared-kernel';cyclesOnly.value=false;error.value='';const clean=new URL(window.location.href);clean.search='';window.history.replaceState({},'',clean)}
onMounted(()=>{window.addEventListener('keydown',shortcut);const p=new URLSearchParams(window.location.search);if(p.get('repo')){url.value=p.get('repo')!;branch.value=p.get('ref')??'';analyze()}});onBeforeUnmount(()=>{controller?.abort();window.removeEventListener('keydown',shortcut)});
</script>
<template>
<div class="app-shell">
<header class="topbar"><a class="brand" href="/" aria-label="Repo X-Ray home"><span class="brand-mark"><Asterisk :size="25" stroke-width="2"/></span>repo<span class="brand-light">x-ray</span><span class="beta">BETA</span></a><div class="topbar-right"><span class="supported"><span class="status-dot"></span> Java architecture explorer</span><a href="https://github.com" target="_blank" rel="noopener noreferrer" class="icon-button" aria-label="Open GitHub"><Github :size="19"/></a></div></header>
<main>
<section class="intro"><div><div class="eyebrow"><span></span> UNDERSTAND BEFORE YOU BUILD</div><h1>See the bigger <em>picture.</em></h1><p>Turn a Java repository into a map of how everything connects.</p></div><div class="intro-note"><GitBranch :size="21"/><span>From source code<br><strong>to a clearer perspective.</strong></span></div></section>
<section class="input-panel" aria-label="Analyze a repository"><form @submit.prevent="analyze"><div class="repo-input"><Github :size="20"/><input v-model="url" type="url" aria-label="Public GitHub repository URL" placeholder="https://github.com/owner/repository" required :disabled="loading" spellcheck="false"/></div><div class="branch-input"><GitBranch :size="15"/><input v-model="branch" aria-label="Branch or tag (optional)" placeholder="Default branch" :disabled="loading"/></div><button type="submit" class="primary-button" :disabled="loading"><LoaderCircle v-if="loading" :size="17" class="spin"/><span>{{ loading?'Analyzing…':'Analyze repository' }}</span><ArrowRight v-if="!loading" :size="17"/></button></form><div class="input-help"><span><span class="tiny-dot"></span> Public repositories only <span class="divider">/</span> Maven & Gradle</span><button class="text-button" @click="loadDemo" :disabled="loading">Explore the demo <ArrowUpRight :size="13"/></button></div></section>
<div v-if="error" class="notice error" role="alert"><CircleAlert :size="18"/><span>{{error}}</span><button @click="error=''" aria-label="Dismiss error"><X :size="16"/></button></div>
<div v-if="loading" class="notice loading-notice" role="status"><LoaderCircle :size="18" class="spin"/><span>Reading build files and tracing module connections. Large repositories can take a little longer.</span></div>
<div v-for="warning in data.warnings" :key="warning" class="notice warning"><CircleAlert :size="17"/><span>{{warning}}</span></div>
<section class="report" :aria-busy="loading">
<div class="report-header"><div class="repo-heading"><span class="repo-avatar"><Box :size="21"/></span><div><div class="repo-name"><span>{{data.repository.owner}} /</span> {{data.repository.name}} <span v-if="isDemo" class="demo-badge">DEMO</span></div><div class="report-subtitle"><GitBranch :size="12"/> {{data.repository.ref?.slice(0,12)||'default branch'}} <span>·</span> {{isDemo?'Illustrative data — not a live repository':'Build-file dependency analysis'}}</div></div></div><button class="secondary-button" @click="share" :disabled="isDemo||loading" :title="isDemo?'Analyze a repository to share its URL':'Copy a link that reruns this analysis'"><Check v-if="copied" :size="14"/><Copy v-else :size="14"/>{{copied?'Link copied':'Share report'}}</button></div>
<div class="stats-grid"><div class="stat"><span><Layers :size="15"/> Modules</span><strong>{{data.stats.modules}}<small>build units</small></strong></div><div class="stat"><span><Link2 :size="15"/> Connections</span><strong>{{data.stats.edges}}<small>internal dependencies</small></strong></div><div class="stat"><span><Box :size="15"/> External dependencies</span><strong>{{data.stats.externalDependencies}}<small>unique coordinates</small></strong></div><div class="stat" :class="{'has-cycles':data.stats.cycles>0}"><span><Activity :size="15"/> Circular groups</span><strong>{{data.stats.cycles}}<small>{{data.stats.cycles?'worth a closer look':'no cycles detected'}}</small></strong></div></div>
<div v-if="data.stats.languages" class="language-strip"><span>{{data.stats.totalFiles}} repository files</span><span v-for="(count,language) in data.stats.languages" :key="language"><i></i>{{language}} <b>{{count}}</b></span></div><div class="workspace"><aside class="module-panel"><div class="panel-tabs"><button :class="{active:tab==='modules'}" @click="tab='modules'">Modules <span>{{data.nodes.length}}</span></button><button :class="{active:tab==='insights'}" @click="tab='insights'">Insights</button></div><template v-if="tab==='modules'"><label class="module-search"><Search :size="14"/><input ref="searchInput" v-model="query" placeholder="Find a module…" aria-label="Filter modules"/><kbd>/</kbd></label><div class="module-list"><button v-for="node in filtered" :key="node.id" class="module-item" :class="{selected:node.id===selected}" @click="selected=node.id"><Box :size="15"/><span>{{node.label}}</span><small>{{connections(data,node.id)}}</small></button><p v-if="!filtered.length" class="empty-message">No modules match your search.</p></div><div class="list-footer"><span class="tiny-dot"></span> {{data.stats.filesScanned}} build files scanned</div></template><div v-else class="insights"><div class="section-label">MOST CONNECTED</div><button v-for="(node,index) in ranked" :key="node.id" class="rank-item" @click="selected=node.id"><span class="rank">0{{index+1}}</span><span>{{node.label}}</span><strong>{{connections(data,node.id)}}</strong></button><div class="section-label cycle-title">CIRCULAR DEPENDENCY GROUPS</div><p v-if="!data.cycles.length" class="empty-message">No cycles detected in the resolved module graph.</p><button v-for="(cycle,index) in data.cycles" :key="index" class="cycle-card" @click="selected=cycle[0];cyclesOnly=true"><Activity :size="14"/><span>{{cycle.map(name).join(', ')}}</span></button></div></aside>
<div class="graph-panel"><div class="graph-toolbar"><div><span class="live-dot"></span><h2>Dependency map</h2><span class="graph-version">{{isDemo?'EXAMPLE':'LIVE REPORT'}}</span></div><button class="cycle-toggle" :disabled="!data.cycles.length" :class="{enabled:cyclesOnly}" @click="cyclesOnly=!cyclesOnly" :aria-pressed="cyclesOnly"><Activity :size="14"/> Highlight cycles</button></div><DependencyGraph v-if="data.nodes.length" :data="data" :selected="selected" :cycles-only="cyclesOnly" @select="selected=$event"/><div v-else class="graph-empty"><Layers :size="35"/><h3>No modules found</h3><p>This repository may not contain supported Maven or Gradle build files.</p></div><div class="graph-legend"><span><i class="legend-module"></i> Module</span><span><i class="legend-line"></i> Depends on</span><span><i class="legend-cycle"></i> Cycle member</span><span class="graph-interaction">Click a module to inspect <ChevronRight :size="12"/></span></div></div>
<aside class="detail-panel"><template v-if="current"><div class="detail-label">MODULE DETAILS <Fingerprint :size="15"/></div><span class="detail-icon"><Box :size="23"/></span><h2>{{current.label}}</h2><span class="build-badge">{{current.buildTool||'Java'}} module</span><div class="detail-section"><div class="section-label">BUILD FILE</div><code>{{current.path||'Root module'}}</code></div><div class="connection-summary"><div><strong>{{incoming.length}}</strong><span>dependents</span></div><div><strong>{{outgoing.length}}</strong><span>dependencies</span></div></div><div class="detail-section"><div class="section-label">DEPENDS ON <span>{{outgoing.length}}</span></div><button v-for="edge in outgoing" :key="edge.target" class="detail-link" @click="selected=edge.target"><Box :size="13"/>{{name(edge.target)}}<ChevronRight :size="13"/></button><p v-if="!outgoing.length" class="muted small">No internal dependencies.</p></div><div class="detail-section"><div class="section-label">EXTERNAL DEPENDENCIES <span>{{current.dependencies?.length||0}}</span></div><div v-for="dependency in current.dependencies" :key="dependency" class="external-dependency">{{dependency}}</div><p v-if="!current.dependencies?.length" class="muted small">None declared.</p></div><a v-if="!isDemo" :href="`${data.repository.url}/blob/${encodeURIComponent(data.repository.ref||'HEAD')}/${current.path.split('/').map(encodeURIComponent).join('/')}`" target="_blank" rel="noopener noreferrer" class="source-link">View build file <ExternalLink :size="13"/></a></template><div v-else class="empty-message">Select a module to explore its dependencies.</div></aside></div>
</section>
<footer><span><Asterisk :size="15"/> A little clarity for complex code.</span><span>Static analysis. No code execution. <span class="footer-divider">·</span> Built for Java.</span></footer>
</main></div>
</template>
